                            .buffer_snapshot()
                            .anchor_after(local_diagnostic.range.end),
                    local_diagnostic.diagnostic.to_owned(),
                );

                let scroll_handle = ScrollHandle::new();

                Some(DiagnosticPopover {
                    local_diagnostic,
                    markdown,
