800	fn parse_file_link(link: &str) -> Option<(PathBuf, Option<String>)> {
801	    let uri = Url::parse(link).ok().filter(|uri| uri.scheme() == "file")?;
802	    let fragment = uri.fragment().map(ToOwned::to_owned);
803	    let path = uri.to_file_path().unwrap_or_else(|_| {
804	        let encoded = uri.path();
805	
806	        urlencoding::decode(encoded)
807	            .map(Cow::into_owned)
808	            .map(PathBuf::from)
809	            .unwrap_or_else(|_| PathBuf::from(encoded))
810	    });
811	
812	    Some((path, fragment))
813	}
