338	pub fn show_link_definition(
339	    shift_held: bool,
340	    editor: &mut Editor,
341	    trigger_point: TriggerPoint,
342	    snapshot: &EditorSnapshot,
343	    window: &mut Window,
344	    cx: &mut Context<Editor>,
