394	            return;
395	        }
396	    } else {
397	        editor.hide_hovered_link(cx)
398	    }
399	    let project = editor.project.clone();
400	    let provider = editor.semantics_provider.clone();
401	
402	    // Record the requested position so a mouse move on the same point short-circuits
403	    // instead of re-querying, even when the server returns no `originSelectionRange`
404	    // (which would otherwise leave `symbol_range` empty).
405	    hovered_link_state.last_trigger_point = trigger_point.clone();
