407	    hovered_link_state.task = Some(cx.spawn_in(window, async move |this, cx| {
408	        async move {
409	            // LSP document links take priority: the server explicitly
410	            // declares which ranges are clickable, so they are more
411	            // accurate than the heuristic-based URL/file detection.
412	            //
413	            // Resolution is deduplicated by `LspStore`; awaiting here only
414	            // blocks until either the cached resolved entry is returned or
