419	                })
420	                .ok()
421	                .flatten();
422	            let resolved_document_links = match resolved_document_links {
423	                Some(task) => task.await,
424	                None => Vec::new(),
425	            };
426	            let snapshot = this.read_with(cx, |editor, cx| editor.buffer.read(cx).snapshot(cx))?;
427	            let detected_document_link =
428	                resolved_document_links
429	                    .into_iter()
430	                    .find_map(|(server_id, link)| {
431	                        let multi_buffer_range =
432	                            snapshot.buffer_anchor_range_to_anchor_range(link.range.clone())?;
433	                        Some((link.range, multi_buffer_range, link.target, server_id))
