437	            let result = match &trigger_point {
438	                TriggerPoint::Text(_) => {
439	                    let mut links = Vec::new();
440	                    let mut symbol_range = None;
441	
442	                    // LSP-provided document link wins over heuristic URL/file
443	                    // detection at the same position: the server tells us the
444	                    // exact range and target, while `find_url`/`find_file` are
445	                    // best-effort text matches.
446	                    if let Some((_, multi_buffer_range, Some(target), server_id)) =
