538	                        || hovered_link_state.symbol_range.is_some();
539	
540	                    if underline_hovered_link {
541	                        let style = HighlightStyle {
542	                            underline: Some(UnderlineStyle {
543	                                thickness: px(1.),
544	                                ..UnderlineStyle::default()
545	                            }),
546	                            color: Some(cx.theme().colors().link_text_hover),
547	                            ..HighlightStyle::default()
548	                        };
549	                        let highlight_range =
550	                            symbol_range.unwrap_or_else(|| match &trigger_point {
551	                                TriggerPoint::Text(trigger_anchor) => {
552	                                    let snapshot = editor.buffer.read(cx).snapshot(cx);
