584	                                HighlightKey::HoveredLinkState,
585	                                vec![highlight],
586	                                style,
587	                                cx,
588	                            ),
589	                        }
590	                    }
591	                } else if let Some((_, multi_buffer_range, _, _)) = detected_document_link.as_ref()
592	                {
593	                    let style = HighlightStyle {
594	                        underline: Some(UnderlineStyle {
595	                            thickness: px(1.),
596	                            ..UnderlineStyle::default()
597	                        }),
598	                        color: Some(cx.theme().colors().link_text_hover),
599	                        ..HighlightStyle::default()
