605	                        cx,
606	                    );
607	                } else {
608	                    // When no links are found, we don't want to completely
609	                    // throw away the `HoveredLinkState`, we'll want to at least
610	                    // keep the `trigger_point` around in order to avoid sending
611	                    // multiple requests for the same point.
612	                    hovered_link_state.links.clear();
613	                }
614	            })?;
615	
616	            anyhow::Ok(())
617	        }
618	        .log_err()
619	        .await
620	    }));
621	
622	    editor.hovered_link_state = Some(hovered_link_state);
623	}
