15	/// A set of diagnostics associated with a given buffer, provided
16	/// by a single language server.
17	///
18	/// The diagnostics are stored in a [`SumTree`], which allows this struct
19	/// to be cheaply copied, and allows for efficient retrieval of the
20	/// diagnostics that intersect a given range of the buffer.
21	#[derive(Clone, Debug)]
22	pub struct DiagnosticSet {
23	    diagnostics: SumTree<DiagnosticEntry<Anchor>>,
24	}
25	
26	/// A single diagnostic in a set. Generic over its range type, because
27	/// the diagnostics are stored internally as [`Anchor`]s, but can be
28	/// resolved to different coordinates types like [`usize`] byte offsets or
29	/// [`Point`](gpui::Point)s.
30	#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
31	pub struct DiagnosticEntry<T> {
32	    /// The range of the buffer where the diagnostic applies.
33	    pub range: Range<T>,
34	    /// The information about the diagnostic.
35	    pub diagnostic: Diagnostic,
36	    /// The related information the language server attached to the diagnostic. Its
37	    /// locations are in the same coordinates as `range`, so that they are converted
38	    /// and followed the same way.
39	    pub related_information: Option<Arc<[RelatedInformation<T>]>>,
40	}
