42	impl<T> DiagnosticEntry<T> {
43	    pub fn new(range: Range<T>, diagnostic: Diagnostic) -> Self {
44	        Self {
45	            range,
46	            diagnostic,
47	            related_information: None,
48	        }
49	    }
50	}
