52	impl<T: Clone> DiagnosticEntry<T> {
53	    /// Converts the entry to a different buffer coordinate type, taking the related
54	    /// information with it so that its locations stay in the same space as the range.
55	    pub fn map_coordinates<O>(
56	        self,
57	        mut map: impl FnMut(&Range<T>) -> Range<O>,
58	    ) -> DiagnosticEntry<O> {
59	        DiagnosticEntry {
60	            range: map(&self.range),
61	            related_information: self.related_information.as_ref().map(|information| {
62	                information
63	                    .iter()
64	                    .map(|information| information.map_location(&mut map))
65	                    .collect()
66	            }),
67	            diagnostic: self.diagnostic,
68	        }
69	    }
70	}
